decoradores:
@Matches(/^[A-Za-z0-9.-]+$/, {
    message: 'El documento sólo admite letras, dígitos, punto y guion',
  })

@Matches(/^[+]?[0-9 ()-]{6,}$/, {
    message: 'El teléfono sólo admite dígitos, espacios, paréntesis, + y guion',
  })

@Matches(/^\d{2}:\d{2}(:\d{2})?$/, {
    message: 'startTime debe tener formato HH:MM o HH:MM:SS',
  })

@Matches(/^\d{2}:\d{2}(:\d{2})?$/, {
    message: 'endTime debe tener formato HH:MM o HH:MM:SS',
  })

